using System;using System.Collections.Generic;using System.Reflection;using System.IO;using System.Xml;using HarmonyLib;using UnityEngine;using Delve;using DelveBatchEleven;
public class ConsoleCmdBatchEleven:ConsoleCmdAbstract {
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}
 public override string[] getCommands(){return new[]{"batch11verify"};}public override string getDescription(){return "Batch eleven native crafting and progression checks.";}
 public override void Execute(List<string> args,CommandSenderInfo sender){EntityPlayer p=null;try{checks=0;p=EntityFactory.CreateEntity(EntityClass.FromString("playerMale"),Vector3.zero) as EntityPlayer;p.world=GameManager.Instance.World;var all=CraftingManager.GetAllRecipes();int gear=0,exchanges=0;var types=new HashSet<int>();
 foreach(var r in all){var v=new ItemValue(r.itemValueType);string skill=Quality.Skill(v);if(skill==null||!types.Add(v.type)||r.IsScrap)continue;gear++;for(int rank=1;rank<=20;rank++){CharacterProgression.Set(p,"delvePractice"+skill,ProficiencyRules.Threshold(rank));Check(r.GetCraftingTier(p)==Quality.Tier(rank),"Craft quality "+r.GetName()+" rank "+rank);}
  foreach(var effect in new[]{PassiveEffects.EntityDamage,PassiveEffects.BlockDamage,PassiveEffects.DegradationMax,PassiveEffects.PhysicalDamageResist}){v.Quality=1;float a=EffectManager.GetValue(effect,v,0,null);v.Quality=6;float b=EffectManager.GetValue(effect,v,0,null);if(a>0)Check(b>a,"Quality improves "+r.GetName()+" "+effect+" "+a+" -> "+b);}
 }
 Check(gear>30,"Craftable gear coverage "+gear);
 foreach(var r in all){var x=Supply.Find(r);if(x==null)continue;exchanges++;Check(r.craftingArea=="delveFarmDispatch","Farm-only exchange");Check(!XUiM_Recipes.FilterRecipesByWorkstation("",all).Contains(r),"Exchange excluded from inventory");Check(r.ingredients.Count>0&&r.craftingToolType==0,"Direct ingredients without circular tools");CharacterProgression.Set(p,"delvePractice"+x.Skill,ProficiencyRules.Threshold(x.Rank));Check(RecipeProgression.Allowed(r,p),"Exchange unlocked "+x.Title);if(x.Rank>1){CharacterProgression.Set(p,"delvePractice"+x.Skill,ProficiencyRules.Threshold(x.Rank-1));Check(!RecipeProgression.Allowed(r,p),"Exchange rank boundary");}
 var station=new TileEntityWorkstation((Chunk)null);station.SetDisableModifiedCheck(true);station.Queue=new[]{new RecipeQueueItem{Recipe=r,Multiplier=2,CraftingTimeLeft=0,OneItemCraftTime=1,Quality=1,StartingEntityId=-1}};var method=AccessTools.Method(typeof(TileEntityWorkstation),"HandleRecipeQueue");method.Invoke(station,new object[]{2f});method.Invoke(station,new object[]{2f});int paid=0;foreach(var s in station.Output)if(s.itemValue.type==r.itemValueType)paid+=s.count;Check(paid==r.count*2,"Native direct payment "+x.Title+" "+paid);}
 Check(exchanges==12,"All exchanges and legacy parcel redemption present");
 var names=new HashSet<string>();foreach(var r in all)if(r.craftingArea!=null&&r.craftingArea.StartsWith("delve"))names.Add(r.craftingArea);foreach(var name in names){var cats=UIDisplayInfoManager.Current.GetCraftingCategoryDisplayList(name);Check(cats!=null&&cats.Count==10,"Ten native filter icons "+name);var recipes=XUiM_Recipes.FilterRecipesByWorkstation(name,all);foreach(var r in recipes){int matches=0;foreach(var c in cats)if(c.Name!="delveCatAll"&&Categories.Matches(c.Name.Substring(8),r))matches++;Check(matches>=1,"Recipe categorized "+name+" "+r.GetName());}foreach(var c in cats){var list=new List<Recipe>(recipes);XUiM_Recipes.FilterRecipesByCategory(c.Name,ref list);foreach(var r in list)Check(Categories.Matches(c.Name.Substring(8),r),"Native category filtering");}}
 var farm=XUiM_Recipes.FilterRecipesByWorkstation("delveFarmDispatch",all);var seeds=new List<Recipe>(farm);XUiM_Recipes.FilterRecipesByCategory("delveCatSeeds",ref seeds);Check(seeds.Count>0&&seeds.TrueForAll(r=>Supply.Find(r)==null),"Seeds isolated from supply orders");var orders=new List<Recipe>(farm);XUiM_Recipes.FilterRecipesByCategory("delveCatOrders",ref orders);Check(orders.Count==12,"Orders isolated from seeds");
 var group=TraderInfo.traderItemGroups[TraderInfo.traderItemGroups.ContainsKey("delveLessonRestock11")?"delveLessonRestock11":"delvelessonrestock11"];var trader=TraderInfo.traderInfoList[1];var rng=new GameRandom();rng.SetSeed(711);var selections=new HashSet<string>();for(int i=0;i<100;i++){var stock=new List<ItemStack>();trader.SpawnItemsFromGroup(rng,group,3,stock,true);var distinct=new HashSet<int>();int count=0;foreach(var s in stock){distinct.Add(s.itemValue.type);count+=s.count;selections.Add(s.itemValue.ItemClass.GetItemName());}Check(count==3&&distinct.Count==3,"Restock exactly three distinct tutorial books "+count+"/"+distinct.Count);}Check(selections.Count==6,"All six lessons can appear");
 foreach(string family in new[]{"Supplies","Provisions","Gear"}){var seen=new HashSet<int>();int bookRolls=0;for(int roll=0;roll<1000;roll++){var reward=LootContainer.GetRewardItem("delveReward11"+family,1);Check(reward!=null&&!reward.IsEmpty()&&reward.count>0,"Native reward valid "+family);seen.Add(reward.itemValue.type);if(reward.itemValue.ItemClass.GetItemName().StartsWith("delveLesson"))bookRolls++;}Check(seen.Count>=6,"Reward variety "+family);if(family=="Gear")Check(bookRolls>0&&bookRolls<180,"Occasional skill books "+bookRolls);}
 p.QuestJournal=new QuestJournal();Check(!Journals.Started(p,"delveLessonAlchemy"),"Fresh lesson accepted");p.Buffs.SetCustomVar(Journals.Key("delveLessonAlchemy"),1);Check(Journals.Started(p,"delveLessonAlchemy"),"Persistent once-only tutorial receipt");Check(!Journals.Started(p,"delveLessonCooking"),"Other tutorial stays available");
 var area=SettlementStorage.Square(new Vector3i(0,60,0),20);Check(area.Contains(new Vector3i(20,200,-20))&&!area.Contains(new Vector3i(21,60,0)),"Settlement full-height boundary");Check(area.Contains(new Vector3i(18,60,0))&&!NearbyCrafting.InRange(18,0,0),"Beyond five meters inside settlement");Check(NearbyCrafting.InRange(5,0,0)&&!NearbyCrafting.InRange(6,0,0),"Outside settlement five-meter fallback");
 Check(BuffManager.GetBuff("delveWorldJournal").Hidden&&BuffManager.GetBuff("delveWayrestProgress").Hidden,"Both HUD counters hidden");var journal=QuestClass.GetQuest("delveWorldProgressJournal11");Check(journal!=null,"Persistent world journal definition");
 var manager=(RegionFileManager)AccessTools.Field(typeof(ChunkProviderGenerateWorld),"m_RegionFileManager").GetValue(p.world.ChunkCache.ChunkProvider);int chunks=0;foreach(long k in manager.GetAllChunkKeys()){Check(manager.GetChunkSync(k)!=null,"Saved chunk loads");chunks++;}
 SdtdConsole.Instance.Output("[Batch11] PASS "+checks+" checks; "+gear+" gear recipes, 20 ranks each; "+exchanges+" native direct exchanges; "+names.Count+" station filters; 100 three-book restocks; lesson guards; settlement boundaries; "+chunks+" saved chunks.");
 }catch(Exception e){SdtdConsole.Instance.Output("[Batch11] FAIL "+e);}finally{if(p!=null)UnityEngine.Object.Destroy(p.gameObject);}}
}
